result_rows = []
left_rows = sql_data.get('v23_sc10_pf_145_left', [])
right_rows = sql_data.get('v23_sc10_pf_145_right', [])
left_totals = {}
right_totals = {}
for row in left_rows:
    k = row.get('asset_code')
    if k != None:
        left_totals[k] = left_totals.get(k, 0) + (row.get('gross_qty', 0) or 0)
for row in right_rows:
    k = row.get('asset_code')
    if k != None:
        right_totals[k] = right_totals.get(k, 0) + (row.get('gross_qty', 0) or 0)
for k, total in left_totals.items():
    net = total - right_totals.get(k, 0)
    result_rows.append({'asset_code': k, 'net_qty': net})
out('joined_totals').append(result_rows)
```

